import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.Dm8zwdB5.js";const g=JSON.parse('{"title":"Sync Triggering (UD-42 Support)","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/responsive-sync-triggering.md","filePath":"integrations/responsive-sync-triggering.md","lastUpdated":1789374597000}'),n={name:"integrations/responsive-sync-triggering.md"};function i(s,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sync-triggering-ud-42-support" tabindex="-1">Sync Triggering (UD-42 Support) <a class="header-anchor" href="#sync-triggering-ud-42-support" aria-label="Permalink to &quot;Sync Triggering (UD-42 Support)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Coming soon!</p><p>Sync Triggering hasn&#39;t shipped yet — this page describes the intended design.</p></div><p>A domain&#39;s local data is a bounded subset of what&#39;s on the server — with no filter applied, a list intentionally shows only what&#39;s already been downloaded. The moment a real filter is applied, that&#39;s a request to see data matching it, which may not exist locally yet. So the filter change triggers a responsive sync (UD-42) that fetches exactly what the new filter needs.</p><h2 id="you-author" tabindex="-1">You author <a class="header-anchor" href="#you-author" aria-label="Permalink to &quot;You author&quot;">​</a></h2><ul><li><strong><code>ResponsiveSyncHandler</code></strong> — the per-scope collaborator that decides whether a sync should run right now, maps the domain&#39;s filter model into an actual sync request, and issues it.</li></ul><h2 id="provided" tabindex="-1">Provided <a class="header-anchor" href="#provided" aria-label="Permalink to &quot;Provided&quot;">​</a></h2><ul><li><strong><code>ResponsiveSyncCoordinator</code></strong> — owns <em>when</em>, not <em>what</em>, so no feature or platform reimplements this timing on its own. It debounces rapid filter edits and plugs straight into the framework&#39;s own write paths — so triggering a sync on a filter change is a couple of constructor parameters, not a hand-rolled coordinator per domain.</li></ul>',7)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
